import * as array from "std/array"
import * as jobs from "ink/task_queue"
import * as ecs from "ink/ecs"
import * as journal from "ink/journal"
import * as messages from "ink/messages"
import * as pages from "ink/pages"
import * as changes from "ink/changes"
import * as schedule from "ink/schedule"

const run_prepared = fn order initial run commit => do:
  let state = initial
  for wave in order:
    let deltas = array.map (fn index => run index state) wave
    for slot in 0 .. wave.length:
      state := commit self wave[slot] deltas[slot]
  return #Some state
const scheduling = fn prepared count => do:
  let plan = #schedule.Plan {
    dependencies: array.generate count (fn i => if i < 16 then #[] else #[i - 16]),
    waves: array.generate ((count + 15) / 16) (fn wave => array.generate (min 16 (count - wave * 16)) (fn slot => wave * 16 + slot))}
  let #Some order = schedule.validate plan else:
    return @panic "valid schedule rejected"
  let result = 0
  for tick in 0 .. 64:
    result := Maybe.unwrap_or 0xFFFFFFFF (if prepared then run_prepared order result (fn i _ => i) (fn state _ delta => state + delta)
      else schedule.execute plan result (fn i _ => i) (fn state _ delta => state + delta))
  return #[result]
entry const schedule_before = scheduling #False
entry const schedule_after = scheduling #True

const pages_cursor = fn (count: U32) (dirty: Array U32) (value: U32 -> a) (before: pages.Pages a) => do:
  if count == before.count && dirty.length == 0:
    return before
  if before.count == 0:
    return pages.from (array.generate count value)
  let selected = changes.unique dirty
  let blocks = array.map (fn index => index >> 6) selected
  return pages.update_pages count blocks (fn page old => do:
    let start = page << 6
    let size = min 64 (count - start)
    let values = array.generate size (fn slot => if start + slot >= before.count then value (start + slot) else old[slot])
    let first = pages.lower_bound selected start
    let last = pages.lower_bound selected (start + size)
    for at in first .. last:
      let index = selected[at]
      if index < before.count:
        values[index - start] := value index
    return values) before

const changed_linear = fn (before: ecs.Column a) (next: ecs.Column a) (selected: Array U32) => do:
  let structural = #False
  let tracked = Maybe.is_some before.journal
  let entries = array.fill (if tracked then selected.length else 0) #journal.Replaced
  let count = 0
  for id in selected:
    let bit = 1 << (id & ecs.leaf_mask)
    let was = ecs.word_mask before.masks (id >> ecs.leaf_bits) & bit != 0
    let now = ecs.word_mask next.masks (id >> ecs.leaf_bits) & bit != 0
    structural := structural || (was && Bool.not now) || (now && Bool.not was)
    if tracked && (now || was):
      let entry = if now then (if was then #journal.Updated id else #journal.Added id) else #journal.Removed id
      entries[count] := entry
      count := self + 1
  next.revision := ecs.bumped_revision before.revision
  next.structure := if structural then ecs.bumped_revision before.structure else before.structure
  next.journal := Maybe.map (journal.record_many (array.slice 0 count entries)) before.journal
  return next

const decode_linear = fn (maximum: U32) (trace: Bool) decode_request decode_value decode_local (words: Array U32) => do:
  if words.length < 7 || words[0] != 1 || words[1] == 0 || words[3] > min 4096 maximum || words[4] > 1 || words[6] > words[3]:
    return #Nothing
  let queue = jobs.make words[1] words[3] trace
  queue.next := words[2]
  queue.open := words[4] == 1
  queue.tick := words[5]
  let out = array.fill words[6] #Nothing
  let offset = 7
  let previous = 0
  for index in 0 .. words[6]:
    if words.length - offset < 8:
      return #Nothing
    let sequence = words[offset]
    let submitted = words[offset + 1]
    let earliest = words[offset + 2]
    let tag = words[offset + 3]
    let ready = words[offset + 4]
    let requests = words[offset + 5]
    let locals = words[offset + 6]
    let values = words[offset + 7]
    if sequence <= previous || (queue.next != 0 && sequence >= queue.next) || submitted > queue.tick || earliest < submitted || tag > 3:
      return #Nothing
    offset := self + 8
    if requests > words.length - offset:
      return #Nothing
    let #Some request = decode_request (array.slice offset requests words) else:
      return #Nothing
    offset := self + requests
    if locals > words.length - offset:
      return #Nothing
    let #Some local = decode_local (array.slice offset locals words) else:
      return #Nothing
    offset := self + locals
    if values > words.length - offset:
      return #Nothing
    let payload = array.slice offset values words
    offset := self + values
    let state = #jobs.Pending
    if tag == 0:
      if values != 0 || ready != 0 || Bool.not queue.open:
        return #Nothing
    else:
      if ready < submitted || ready > queue.tick || (Bool.not queue.open && tag != 3):
        return #Nothing
      let outcome = #jobs.Failed 0
      if tag == 1:
        let #Some value = decode_value payload else:
          return #Nothing
        outcome := #jobs.Value value
      else:
        if values != 1:
          return #Nothing
        outcome := if tag == 2 then #jobs.Failed payload[0] else #jobs.Cancelled payload[0]
      state := #jobs.Ready { tick: ready, outcome }
    out[index] := #Some (#jobs.Job { ticket: #jobs.Ticket { epoch: queue.epoch, sequence }, submitted, earliest, request, continuation: local, state })
    previous := sequence
  if offset != words.length:
    return #Nothing
  queue.jobs := array.map (fn item => case item of
    #Some job => job
    #Nothing => @panic "decoder count invariant") out
  return #Some queue

const publish_linear = fn (tick: U32) (queue: jobs.Queue [request, value, local]) => do:
  if tick < queue.tick:
    return @panic "task delivery tick moved backwards"
  let count = 0
  for job in queue.jobs:
    let #jobs.Ready { tick: ready, outcome } = job.state else:
      break
    if tick < ready || tick < job.earliest:
      break
    queue := jobs.mark job.ticket tick #jobs.Published self
    count := self + 1
  let delivered = array.generate count (fn i => do:
    let job = queue.jobs[i]
    let #jobs.Ready {outcome} = job.state else:
      return @panic "ready prefix invariant"
    return #jobs.Delivery {ticket: job.ticket, continuation: job.continuation, outcome})
  queue.jobs := array.slice count (self.length - count) self
  queue.tick := tick
  return (queue, delivered)

const queue = fn count => do:
  let q: jobs.Queue [U32, U32, U32] = jobs.make 1 count #False
  q.next := count + 1
  q.tick := 1
  q.jobs := array.generate count (fn i => #jobs.Job {ticket: #jobs.Ticket {epoch: 1, sequence: i + 1}, submitted: 0, earliest: 1,
    request: i, continuation: i * 3, state: #jobs.Ready {tick: 1, outcome: case i % 3 of
      0 => #jobs.Value (i * 5)
      1 => #jobs.Failed (i * 7)
      _ => #jobs.Cancelled (i * 11)}})
