use ink_tools::{Fixture, compiled};
use blot_host::Value;
use serde_json::json;
use std::time::Instant;

fn main() {
    std::fs::create_dir_all(".cache/more-review").unwrap();
    let verify_only = std::env::args().any(|a| a == "--verify");
    let module = compiled(".cache/more-review/probe.blot", &[]);
    let mut guest = Fixture::from_module(&module);
    let mut report = vec![];
    for count in [0u32, 1, 63, 64, 65, 4097] {
        assert_eq!(guest.call("edges_before", count).unwrap(), guest.call("edges_after", count).unwrap());
    }
    for seed in 0u32..512 {
        assert_eq!(guest.call("bad_before", seed).unwrap(), guest.call("bad_after", seed).unwrap());
    }
    for (scalar, vector, sizes) in [
        ("decode_before", "decode_after", vec![256u32, 1024, 4096]),
        ("publish_before", "publish_after", vec![256, 1024, 4096]),
        ("journal_before", "journal_after", vec![1024, 4096, 16384]),
        ("sparse_before", "sparse_after", vec![4096, 32768, 65536]),
        ("dense_before", "dense_after", vec![4096, 32768, 65536]),
        ("schedule_before", "schedule_after", vec![16u32, 256, 1024]),
    ] {
        for size in sizes {
            let expected = guest.call(scalar, size).unwrap();
            assert_eq!(expected, guest.call(vector, size).unwrap());
            let outcome = |i: u32| i * [5, 7, 11][(i % 3) as usize];
            let mut words: Vec<u32> = vec![];
            match scalar {
                "decode_before" => {
                    words.extend([1,1,size+1,size,1,1,size]);
                    for i in 0..size { words.extend([i+1,0,1,i%3+1,1,1,1,1,i,i*3,outcome(i)]); }
                }
                "publish_before" => {
                    words.extend([0,1,size,size]);
                    for i in 0..size { words.extend([i+1,1,i*3,i%3+1,outcome(i)]); }
                }
                "journal_before" => {
                    words.extend([8,12,7,11]);
                    for i in 0..size { words.extend([if i%2 == 0 {2} else {3},i]); }
                }
                "sparse_before" | "dense_before" => {
                    let stride = if scalar == "sparse_before" {64} else {1};
                    words.extend([0,size-1,size]);
                    for i in 0..size {words.push(i + if i%stride == 0 {1600000} else {0});}
                }
                "schedule_before" => words.push(size*(size-1)/2*64),
                _ => unreachable!(),
            }
            assert_eq!(expected, Value::ArrayU32(words));
            if verify_only {continue;}

            for _ in 0..8 {
                assert_eq!(expected, guest.call(scalar, size).unwrap());
                assert_eq!(expected, guest.call(vector, size).unwrap());
            }
            let memory_before = guest.guest.memory_bytes();
            let mut samples = [vec![], vec![]];
            for round in 0..15 {
                for mode in if round % 2 == 0 { [0, 1] } else { [1, 0] } {
                    let name = if mode == 0 { scalar } else { vector };
                    let start = Instant::now();
                    let actual = guest.call(name, size).unwrap();
                    let elapsed = start.elapsed().as_secs_f64() * 1000.0;
                    assert_eq!(actual, expected);
                    samples[mode].push(elapsed);
                }
            }
            let memory_after = guest.guest.memory_bytes();
            assert_eq!(memory_before, memory_after);
            let medians: Vec<_> = samples
                .iter()
                .map(|v| {
                    let mut v = v.clone();
                    v.sort_by(f64::total_cmp);
                    v[v.len() / 2]
                })
                .collect();
            println!(
                "{scalar} {size}: {:.4} -> {:.4} ms ({:.2}x)",
                medians[0],
                medians[1],
                medians[0] / medians[1]
            );
            report.push(json!({"scalar":scalar,"vector":vector,"size":size,"medianMs":medians,"samplesMs":samples,"committedMemoryBytes":memory_after,"replayGrowthBytes":memory_after-memory_before}));
        }
    }
    if verify_only {println!("Independent witnesses, 512 decoder mutations, and six grow/shrink boundaries passed"); return;}
    std::fs::write(".cache/more-review/all.json",serde_json::to_vec_pretty(&json!({"includes":"fixture construction, guest execution and complete result decoding; alternating paired order; 8 warmups and 15 samples; complete output equality outside timings","results":report})).unwrap()).unwrap();
}
